use serde::{Deserialize, Serialize};
use serde_json::Value;

/// Reference to a durable artifact on disk (e.g. a rendered PDF).
///
/// Only metadata is stored in PostgreSQL; the bytes live in the configured
/// artifact directory. `relative_path` is always generated by the engine
/// (`<job_id>.pdf`), never taken from user input, and is re-validated on read
/// to prevent path traversal.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ArtifactRef {
    pub relative_path: String,
    pub content_type: String,
    pub size_bytes: u64,
    pub sha256: String,
}

/// What a successful handler returns: a small inline JSON result (stored as
/// JSONB) and optionally an artifact reference.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct JobOutput {
    pub result: Value,
    pub artifact: Option<ArtifactRef>,
}

impl JobOutput {
    pub fn inline(result: Value) -> Self {
        Self {
            result,
            artifact: None,
        }
    }
}
